strategy_source:character:
function (ctx, params) 
{
    target <- ctx$hold()
    set <- params$plan[[substr(ctx$ts_utc, 1L, 10L)]]
    for (id in intersect(names(set), names(target))) target[[id]] <- set[[id]]
    if (isTRUE(params$plan$state)) 
        return(list(targets = target, state_update = list(ts = ctx$ts_utc, n = length(target))))
    target
}
